function ame2_safe_error(Throwable $e):array{$m=$e->getMessage();return['class'=>get_class($e),'reason'=>preg_match('/^[A-Za-z0-9_.:-]{1,120}$/D',$m)?$m:'sanitized_supplier_failure'];}
