        catch(Throwable $e){$err=ame2_safe_error($e)+['request_index'=>$idx,'state_key'=>(int)$sk,'operator_key'=>$op,'page'=>$page,'request_sha256'=>$req];$errors[]=$err;ame_write($outDir.'/failure-'.str_pad((string)$idx,3,'0',STR_PAD_LEFT).'.json',$err+['operation_id'=>AME2_OP,'source_sha'=>$sha,'state'=>'supplier_request_failed_no_retry','no_replay'=>true]);break;}
